window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-236fc505879a8aa3"]={"versions": [{"id": "FIG-236fc505879a8aa3", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierungs-Muster für abstrakte Strukturen im AUTOSAR Generic Structure Template (TPS Generic Structure Template). Dargestellt wird die Definition abstrakter Eigenschaften und Assoziationen auf Metaklassen-Ebene sowie deren Konkretisierung, Spezialisierung und Redefinition bzw. Subset-Bildung in abgeleiteten konkreten Klassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Klassen sowie ein Notizelement:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractSuperClass</code> (kursiv, abstrakt): Abstrakte Basisklasse mit ausgehenden abstrakten Assoziationen und Kompositionen zu <code>AbstractFeature</code>.</li>\n<li><code>+/atpReference</code>: Assoziation mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpOtherReference</code>: Assoziation mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>1..*</code>, Eigenschaft <code>{union}</code>.</li>\n<li><code>+/atpFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpUnionFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>0..*</code>, Eigenschaft <code>{union}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>AbstractFeature</code> (kursiv, abstrakt): Abstraktes Ziel-Element der abstrakten Relationen.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteClass</code>: Konkrete Spezialisierung von <code>AbstractSuperClass</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractSuperClass</code>).</li>\n<li><code>+myReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{redefines atpReference}</code>.</li>\n<li><code>+myOtherReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFurtherOtherReference</code>: Zweite Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFeature</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpFeature}</code>.</li>\n<li><code>+myUnionFeatures</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>0..*</code> und Eigenschaft <code>{subsets atpUnionFeature}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteFeature</code>: Konkrete Spezialisierung von <code>AbstractFeature</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractFeature</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Notiz <code>corresponding ...</code>: Rechts platziertes Kommentarfeld, das über gestrichelte Linien die abstrakte Assoziation <code>+/atpReference</code> mit der konkreten redefinierenden Assoziation <code>+myReference</code> verbindet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensdarstellung. Es visualisiert strukturelle Vererbungsbeziehungen, Abstraktions- und Konkretisierungsregeln sowie Konsistenzbedingungen zwischen abgeleiteten/abstrakten Rollen und konkreten Rollen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Musterarchitektur für die AUTOSAR-M2-Metamodellierung:</p>\n<ul class=\"fig-list\">\n<li>Abstrakte Rollennamen beginnen mit dem Präfix <code>atp</code> (AUTOSAR Template Pattern) und sind als abgeleitet (<code>/</code>) sowie stereotypisiert (<code>«atpAbstract»</code>, optional <code>«atpDerived»</code>) deklariert.</li>\n<li>Konkrete Metaklassen müssen von den abstrakten Schablonen erben und deren abstrakte Rollen entweder über <code>{redefines ...}</code> (1:1-Ersetzung) oder über <code>{subsets ...}</code> (Teilmengenbildung bei abgeleiteten Vereinigungen <code>{union}</code>) realisieren.</li>\n<li>Generatoren und M2-Prüfregeln fordern die semantische und typologische Entsprechung zwischen den redefinierten/untergeordneten Eigenschaften konkreter Klassen und den abstrakten Vorgaben.</li>\n</ul>"}, {"id": "FIG-9b44970d04cdf617", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierungs-Muster für abstrakte Strukturen im AUTOSAR Generic Structure Template (TPS Generic Structure Template). Dargestellt wird die Definition abstrakter Eigenschaften und Assoziationen auf Metaklassen-Ebene sowie deren Konkretisierung, Spezialisierung und Redefinition bzw. Subset-Bildung in abgeleiteten konkreten Klassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Klassen sowie ein Notizelement:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractSuperClass</code> (kursiv, abstrakt): Abstrakte Basisklasse mit ausgehenden abstrakten Assoziationen und Kompositionen zu <code>AbstractFeature</code>.</li>\n<li><code>+/atpReference</code>: Assoziation mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpOtherReference</code>: Assoziation mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>1..*</code>, Eigenschaft <code>{union}</code>.</li>\n<li><code>+/atpFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpUnionFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>0..*</code>, Eigenschaft <code>{union}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>AbstractFeature</code> (kursiv, abstrakt): Abstraktes Ziel-Element der abstrakten Relationen.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteClass</code>: Konkrete Spezialisierung von <code>AbstractSuperClass</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractSuperClass</code>).</li>\n<li><code>+myReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{redefines atpReference}</code>.</li>\n<li><code>+myOtherReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFurtherOtherReference</code>: Zweite Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFeature</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpFeature}</code>.</li>\n<li><code>+myUnionFeatures</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>0..*</code> und Eigenschaft <code>{subsets atpUnionFeature}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteFeature</code>: Konkrete Spezialisierung von <code>AbstractFeature</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractFeature</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Notiz <code>corresponding ...</code>: Im mittleren Leerraum zwischen den Klassenblöcken platziertes Kommentarfeld, das über gestrichelte Linien die abstrakte Assoziation <code>+/atpReference</code> mit der konkreten redefinierenden Assoziation <code>+myReference</code> verbindet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensdarstellung. Es visualisiert strukturelle Vererbungsbeziehungen, Abstraktions- und Konkretisierungsregeln sowie Konsistenzbedingungen zwischen abgeleiteten/abstrakten Rollen und konkreten Rollen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Musterarchitektur für die AUTOSAR-M2-Metamodellierung:</p>\n<ul class=\"fig-list\">\n<li>Abstrakte Rollennamen beginnen mit dem Präfix <code>atp</code> (AUTOSAR Template Pattern) und sind als abgeleitet (<code>/</code>) sowie stereotypisiert (<code>«atpAbstract»</code>, optional <code>«atpDerived»</code>) deklariert.</li>\n<li>Konkrete Metaklassen müssen von den abstrakten Schablonen erben und deren abstrakte Rollen entweder über <code>{redefines ...}</code> (1:1-Ersetzung) oder über <code>{subsets ...}</code> (Teilmengenbildung bei abgeleiteten Vereinigungen <code>{union}</code>) realisieren.</li>\n<li>Generatoren und M2-Prüfregeln fordern die semantische und typologische Entsprechung zwischen den redefinierten/untergeordneten Eigenschaften konkreter Klassen und den abstrakten Vorgaben.</li>\n</ul>"}, {"id": "FIG-e5e847fcab599ffb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierungs-Muster für abstrakte Strukturen im AUTOSAR Generic Structure Template (TPS Generic Structure Template). Dargestellt wird die Definition abstrakter Eigenschaften und Assoziationen auf Metaklassen-Ebene sowie deren Konkretisierung, Spezialisierung und Redefinition bzw. Subset-Bildung in abgeleiteten konkreten Klassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Klassen sowie ein Notizelement:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractSuperClass</code> (kursiv, abstrakt): Abstrakte Basisklasse mit ausgehenden abstrakten Assoziationen und Kompositionen zu <code>AbstractFeature</code>.</li>\n<li><code>+/atpReference</code>: Assoziation mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpOtherReference</code>: Assoziation mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>1..*</code>, Eigenschaft <code>{union}</code>.</li>\n<li><code>+/atpFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotyp <code>«atpAbstract»</code>, Multiplizität <code>1</code>.</li>\n<li><code>+/atpUnionFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>) mit Stereotypen <code>«atpAbstract,atpDerived»</code>, Multiplizität <code>0..*</code>, Eigenschaft <code>{union}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>AbstractFeature</code> (kursiv, abstrakt): Abstraktes Ziel-Element der abstrakten Relationen.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteClass</code>: Konkrete Spezialisierung von <code>AbstractSuperClass</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractSuperClass</code>).</li>\n<li><code>+myReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{redefines atpReference}</code>.</li>\n<li><code>+myOtherReference</code>: Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFurtherOtherReference</code>: Zweite Assoziation zu <code>ConcreteFeature</code> mit Eigenschaft <code>{subsets atpOtherReference}</code>.</li>\n<li><code>+myFeature</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpFeature}</code>.</li>\n<li><code>+myUnionFeatures</code>: Komposition zu <code>ConcreteFeature</code> mit Multiplizität <code>0..*</code> und Eigenschaft <code>{subsets atpUnionFeature}</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><code>ConcreteFeature</code>: Konkrete Spezialisierung von <code>AbstractFeature</code> (Generalisierungspfeil mit geschlossener, weißer Spitze auf <code>AbstractFeature</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Notiz <code>corresponding ...</code>: Im mittleren Leerraum zwischen den Klassenblöcken platziertes Kommentarfeld, das über gestrichelte Linien die abstrakte Assoziation <code>+/atpReference</code> mit der konkreten redefinierenden Assoziation <code>+myReference</code> verbindet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensdarstellung. Es visualisiert strukturelle Vererbungsbeziehungen, Abstraktions- und Konkretisierungsregeln sowie Konsistenzbedingungen zwischen abgeleiteten/abstrakten Rollen und konkreten Rollen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Musterarchitektur für die AUTOSAR-M2-Metamodellierung:</p>\n<ul class=\"fig-list\">\n<li>Abstrakte Rollennamen beginnen mit dem Präfix <code>atp</code> (AUTOSAR Template Pattern) und sind als abgeleitet (<code>/</code>) sowie stereotypisiert (<code>«atpAbstract»</code>, optional <code>«atpDerived»</code>) deklariert.</li>\n<li>Konkrete Metaklassen müssen von den abstrakten Schablonen erben und deren abstrakte Rollen entweder über <code>{redefines ...}</code> (1:1-Ersetzung) oder über <code>{subsets ...}</code> (Teilmengenbildung bei abgeleiteten Vereinigungen <code>{union}</code>) realisieren.</li>\n<li>Generatoren und M2-Prüfregeln fordern die semantische und typologische Entsprechung zwischen den redefinierten/untergeordneten Eigenschaften konkreter Klassen und den abstrakten Vorgaben.</li>\n</ul>"}], "trans": [{"from": "FIG-236fc505879a8aa3", "to": "FIG-9b44970d04cdf617", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Notizsymbol „corresponding ...“: Von der rechten Seite des Diagramms in den zentralen Bereich zwischen die Klassen verschoben; die gestrichelten Verbindungslinien zu den Assoziationen <code>atpReference</code> und <code>myReference</code> verlaufen entsprechend angepasst.</li>\n</ul>"}, {"from": "FIG-9b44970d04cdf617", "to": "FIG-e5e847fcab599ffb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
